const body = $input.first().json.body;
const required = ['submitter_name', 'submitter_email', 'expense_items', 'period'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
if (!Array.isArray(body.expense_items) || body.expense_items.length === 0) {
  return [{ json: { valid: false, error: 'expense_items must be a non-empty array' } }];
}
const items = body.expense_items.map((item, i) => {
  const amount = parseFloat(item.amount);
  if (isNaN(amount) || amount <= 0) return null;
  return {
    lineId: `L${String(i+1).padStart(3,'0')}`,
    date: item.date || '',
    description: (item.description || '').trim().slice(0, 200),
    category: item.category || 'uncategorized',
    amount: parseFloat(amount.toFixed(2)),
    currency: item.currency || body.currency || 'USD',
    merchant: item.merchant || '',
    receiptProvided: item.receipt_provided === true || item.receipt_provided === 'true',
    projectCode: item.project_code || body.default_project_code || '',
    notes: (item.notes || '').slice(0, 200)
  };
}).filter(Boolean);
if (items.length === 0) return [{ json: { valid: false, error: 'No valid expense items found' } }];
const totalAmount = items.reduce((s, i) => s + i.amount, 0);
const reportId = `EXP-${Date.now()}`;
return [{ json: {
  valid: true,
  reportId,
  submitterName: body.submitter_name.trim(),
  submitterEmail: body.submitter_email.trim(),
  submitterDepartment: body.submitter_department || '',
  submitterManager: body.submitter_manager || '',
  managerEmail: body.manager_email || '',
  period: body.period.trim(),
  currency: body.currency || 'USD',
  items,
  totalAmount: parseFloat(totalAmount.toFixed(2)),
  itemCount: items.length,
  purpose: (body.purpose || '').slice(0, 400),
  policyLimits: body.policy_limits || {},
  submittedAt: new Date().toISOString()
} }];

const input = $input.first().json;
const items = input.items;
const policy = input.policyLimits;

// Category analysis
const byCategory = {};
for (const item of items) {
  if (!byCategory[item.category]) byCategory[item.category] = { total: 0, count: 0, items: [] };
  byCategory[item.category].total += item.amount;
  byCategory[item.category].count++;
  byCategory[item.category].items.push(item);
}

// Policy checks
const flags = [];
const MEAL_LIMIT = parseFloat(policy.meal_per_diem) || 75;
const ENTERTAINMENT_LIMIT = parseFloat(policy.entertainment_limit) || 150;
const RECEIPT_REQUIRED_ABOVE = parseFloat(policy.receipt_required_above) || 25;
const MAX_SINGLE_ITEM = parseFloat(policy.max_single_item) || 500;

for (const item of items) {
  if (!item.receiptProvided && item.amount > RECEIPT_REQUIRED_ABOVE) {
    flags.push({ lineId: item.lineId, type: 'missing_receipt', severity: 'medium', message: `Receipt required for ${input.currency}${item.amount} (${item.description})` });
  }
  if (item.amount > MAX_SINGLE_ITEM) {
    flags.push({ lineId: item.lineId, type: 'high_value', severity: 'high', message: `Single item exceeds ${input.currency}${MAX_SINGLE_ITEM} limit: ${input.currency}${item.amount}` });
  }
  if ((item.category === 'meals' || item.category === 'food') && item.amount > MEAL_LIMIT) {
    flags.push({ lineId: item.lineId, type: 'over_per_diem', severity: 'medium', message: `Meal expense ${input.currency}${item.amount} exceeds per diem limit of ${input.currency}${MEAL_LIMIT}` });
  }
  if (item.category === 'entertainment' && item.amount > ENTERTAINMENT_LIMIT) {
    flags.push({ lineId: item.lineId, type: 'over_entertainment_limit', severity: 'high', message: `Entertainment expense ${input.currency}${item.amount} exceeds limit of ${input.currency}${ENTERTAINMENT_LIMIT}` });
  }
  if (!item.date) {
    flags.push({ lineId: item.lineId, type: 'missing_date', severity: 'low', message: `No date for: ${item.description}` });
  }
}

const missingReceipts = items.filter(i => !i.receiptProvided && i.amount > RECEIPT_REQUIRED_ABOVE);
const highSeverityFlags = flags.filter(f => f.severity === 'high');
const recommendation = highSeverityFlags.length > 0 ? 'review_required' : flags.length > 2 ? 'flagged_for_review' : missingReceipts.length > 0 ? 'pending_receipts' : 'approve';

return [{ json: {
  input,
  byCategory,
  flags,
  missingReceipts,
  highSeverityFlags,
  recommendation,
  policyUsed: { MEAL_LIMIT, ENTERTAINMENT_LIMIT, RECEIPT_REQUIRED_ABOVE, MAX_SINGLE_ITEM }
} }];

values.content:
Review this expense report.

Submitter: {{ $json.input.submitterName }} ({{ $json.input.submitterDepartment || 'no dept' }})
Period: {{ $json.input.period }}
Total: {{ $json.input.currency }}{{ $json.input.totalAmount }}
Items: {{ $json.input.itemCount }}
Purpose: {{ $json.input.purpose || 'not stated' }}

Category breakdown:
{{ Object.entries($json.byCategory).map(([cat, d]) => `- ${cat}: ${$json.input.currency}${d.total.toFixed(2)} (${d.count} items)`).join('\n') }}

Policy flags ({{ $json.flags.length }}):
{{ $json.flags.map(f => `- [${f.severity.toUpperCase()}] ${f.message}`).join('\n') || 'none' }}

Recommendation: {{ $json.recommendation.replace(/_/g,' ') }}

Give: brief summary of what the report covers, explanation of any flags, and your recommendation with reasoning.
